from typing import List

class Solution:
    """
    Returns the element that appears
    only once in the sorted array.
    """
    def single_non_duplicate(self, arr: List[int]) -> int:
        # Handle the smallest possible input directly.
        if len(arr) == 1:
            return arr[0]

        # Check expected pairs one by one.
        for i in range(0, len(arr) - 1, 2):
            # If the pair breaks here, this value has no partner.
            if arr[i] != arr[i + 1]:
                return arr[i]

        return arr[-1]


# Driver code starts
def main() -> None:
    arr: List[int] = [1, 1, 2, 3, 3, 4, 4, 8, 8]

    obj = Solution()
    print(obj.single_non_duplicate(arr))


if __name__ == "__main__":
    main()
